package net.civeira.phylax.features.document.templateasset.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.document.templateasset.domain.TemplateAsset;
import net.civeira.phylax.features.document.templateasset.domain.event.TemplateAssetEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class TemplateAssetEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<TemplateAssetEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final TemplateAsset entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
